static void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }

/* Sift a[i] down within the heap a[0..size-1] */
static void heapify(int a[], int size, int i) {
    for (;;) {
        int largest = i, l = 2 * i + 1, r = 2 * i + 2;
        if (l < size && a[l] > a[largest]) largest = l;
        if (r < size && a[r] > a[largest]) largest = r;
        if (largest == i) return;           /* heap property holds */
        swap(&a[i], &a[largest]);
        i = largest;
    }
}

void heap_sort(int a[], int n) {
    for (int i = n / 2 - 1; i >= 0; i--)    /* build max-heap in O(n) */
        heapify(a, n, i);
    for (int end = n - 1; end > 0; end--) { /* move max to the end */
        swap(&a[0], &a[end]);
        heapify(a, end, 0);                 /* heap is now a[0..end-1] */
    }
}
